    C("Le récit : roman et nouvelle", "2nde-recit",
      ["Le récit raconte une histoire réelle ou imaginaire. Le roman est long et complexe ; la nouvelle est brève, avec peu de personnages et une chute.",
       "L'analyse porte sur le narrateur, le point de vue, le temps et les personnages."],
      ["Schéma narratif : situation initiale, élément perturbateur, péripéties, élément de résolution, situation finale.",
       "Narrateur interne (je, personnage) ou externe (il) ; focalisation interne, externe, omnisciente.",
       "Temps du récit : passé simple (actions), imparfait (descriptions, habitudes) ; retours en arrière (analepses), ellipses.",
       "Portrait : physique et moral ; personnage principal, secondaires.",
       "Nouvelles africaines : Sembène Ousmane (Voltaïque), Birago Diop ; romans : Une si longue lettre, L'Aventure ambiguë, Les Bouts de bois de Dieu."],
      [("Repérer le schéma", ["Un pêcheur vit en paix (initiale) ; une tempête l'emporte au large (perturbateur) ; il lutte (péripéties) ; des pêcheurs le sauvent (résolution) ; il retrouve sa famille (finale)."]),
       ("La chute", ["Dans une nouvelle, la fin surprend souvent le lecteur et éclaire tout le récit."])],
      "Questions sur le récit.",
      [("Événement qui rompt l'équilibre de départ :", "l'élément perturbateur", "la situation finale", "la chute", "le portrait", "Il lance l'action."),
       ("Récit bref, peu de personnages, fin surprenante :", "la nouvelle", "le roman", "l'épopée", "la fable", "Genre court."),
       ("Temps des descriptions dans un récit au passé :", "l'imparfait", "le passé simple", "le futur", "le conditionnel", "Arrière-plan."),
       ("Un narrateur qui dit « je » et participe à l'histoire :", "narrateur interne", "narrateur externe", "narrateur omniscient absent", "aucun narrateur", "Narrateur-personnage."),
       ("Retour en arrière dans un récit :", "une analepse", "une ellipse", "une prolepse", "une chute", "On revient sur des faits antérieurs.")]),
    C("Figures de style et vocabulaire", "2nde-figures",
      ["Les figures de style enrichissent l'expression. Il faut savoir les nommer et expliquer leur effet.",
       "Le vocabulaire précis et la connaissance des familles de mots aident à comprendre et à écrire."],
      ["Comparaison (avec outil) et métaphore (sans outil) ; personnification.",
       "Hyperbole (exagération), litote (dire moins pour suggérer plus), euphémisme (adoucir).",
       "Antithèse (opposition), oxymore (deux mots contradictoires associés), anaphore (répétition en début de phrase).",
       "Périphrase (expression qui remplace un mot), métonymie (un mot pour un autre lié).",
       "Familles de mots, préfixes, suffixes ; registres de langue : familier, courant, soutenu."],
      [("Métaphore", ["« Dakar, cette ruche bourdonnante » : la ville est comparée à une ruche sans outil de comparaison."]),
       ("Registres de langue", ["bagnole (familier), voiture (courant), automobile (soutenu)."])],
      "Identifie la figure ou le registre.",
      [("« Le vent hurlait dans les arbres » :", "personnification", "comparaison", "litote", "antithèse", "Le vent a un comportement humain."),
       ("« Ce n'est pas mauvais » pour dire « c'est très bon » :", "litote", "hyperbole", "métaphore", "anaphore", "On dit moins pour suggérer plus."),
       ("« La capitale du Sénégal » pour Dakar :", "périphrase", "oxymore", "litote", "comparaison", "Expression qui remplace le nom."),
       ("« Fric » appartient au registre :", "familier", "soutenu", "courant", "technique", "Argent (courant), pécune (soutenu)."),
       ("« Il est fort comme un lion » :", "comparaison", "métaphore", "euphémisme", "chiasme", "Outil de comparaison « comme ».")]),
