      [("Le dividende démographique", ["Beaucoup de jeunes actifs pour peu de personnes à charge : une chance si l'éducation et l'emploi suivent."]),
       ("Dakar", ["La région concentre près d'un quart de la population du Sénégal sur moins de 1 % du territoire."])],
      "Questions sur l'Afrique.",
